import{_ as t,o as s,a as e,b as l}from"./app.C41L12d5.js";const S=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"基础API","link":"/api/SIMD-API/basic_api/basic_api"},{"text":"特殊寄存器访问","link":"/api/SIMD-API/basic_api/special_register_access/special_register_access"},{"text":"GetSaturationStrategy","link":"/api/SIMD-API/basic_api/special_register_access/GetSaturationStrategy"}]},"headers":[],"relativePath":"api/SIMD-API/basic_api/special_register_access/GetSaturationStrategy.md","filePath":"api/SIMD-API/basic_api/special_register_access/GetSaturationStrategy.md","outlineHeaders":[{"level":2,"title":"产品支持情况","slug":"产品支持情况","link":"#产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明","link":"#功能说明"},{"level":2,"title":"函数原型","slug":"函数原型","link":"#函数原型"},{"level":2,"title":"参数说明","slug":"参数说明","link":"#参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明","link":"#返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明","link":"#约束说明"},{"level":2,"title":"调用示例","slug":"调用示例","link":"#调用示例"}],"lastUpdated":1788255258000}'),i={name:"api/SIMD-API/basic_api/special_register_access/GetSaturationStrategy.md"};function n(r,a,c,p,d,o){return s(),e("div",null,[...a[0]||(a[0]=[l(`<div><article class="markdown-body"><h1>GetSaturationStrategy</h1><h2 id="产品支持情况">产品支持情况<a class="header-anchor" href="#产品支持情况">​</a></h2><div data-filter="950"><ul><li>Ascend 950PR/Ascend 950DT：支持</li></ul></div><div data-filter="A3"><ul><li>Atlas A3 训练系列产品/Atlas A3 推理系列产品：不支持</li></ul></div><div data-filter="910b"><ul><li>Atlas A2 训练系列产品/Atlas A2 推理系列产品：不支持</li></ul></div><div data-filter="310b"><ul><li>Atlas 200I/500 A2 推理产品：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品AI Core：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品Vector Core：不支持</li></ul></div><div data-filter="910"><ul><li>Atlas 训练系列产品：不支持</li></ul></div><div data-filter="x90"><ul><li>Kirin X90：不支持</li></ul></div><div data-filter="9030"><ul><li>Kirin 9030：不支持</li></ul></div><h2 id="功能说明">功能说明<a class="header-anchor" href="#功能说明">​</a></h2><p>头文件路径为：<code>&quot;basic_api/kernel_operator_common_intf.h&quot;</code>。</p><p>获取精度转换接口当前使用的饱和模式配置策略。饱和模式用于处理精度转换过程中结果溢出或出现INF/NAN的场景，详细说明请参考<a href="SetSaturationFlag_ISASI.html#%E5%8A%9F%E8%83%BD%E8%AF%B4%E6%98%8E">SetSaturationFlag功能说明</a>。该接口用于查询通过<a href="SetSaturationStrategy.html">SetSaturationStrategy</a>选择的配置来源，主要与Memory矢量计算的<a href="../memory_vector_compute/type_conversion/Cast.html">Cast</a>和Reg矢量计算的<a href="../reg_vector_compute/type_conversion/Cast.html">Cast</a>配合使用：</p><ul><li>使用接口自身的饱和配置时，Reg矢量计算Cast通过<code>CastTrait::satMode</code>配置单接口的饱和或非饱和模式；Memory矢量计算Cast不提供单接口饱和模式参数，其单接口配置为饱和模式。</li><li>使用全局饱和配置时，两类Cast均使用<a href="SetSaturationFlag_ISASI.html">SetSaturationFlag</a>设置的全局饱和模式。</li></ul><h2 id="函数原型">函数原型<a class="header-anchor" href="#函数原型">​</a></h2><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="n">OverrideStrategy</span><span class="w"> </span><span class="n">GetSaturationStrategy</span><span class="p">()</span>
</code></pre></div><h2 id="参数说明">参数说明<a class="header-anchor" href="#参数说明">​</a></h2><p>无</p><h2 id="返回值说明">返回值说明<a class="header-anchor" href="#返回值说明">​</a></h2><p>返回值类型为<code>OverrideStrategy</code>，表示当前使用的饱和模式配置策略。</p><p><strong>表1</strong> 返回值说明</p><table><thead><tr><th>返回值</th><th>描述</th></tr></thead><tbody><tr><td><code>OverrideStrategy::USE_API</code></td><td>使用精度转换接口自身的饱和配置。</td></tr><tr><td><code>OverrideStrategy::USE_GLOBAL</code></td><td>使用<a href="SetSaturationFlag_ISASI.html">SetSaturationFlag</a>设置的全局饱和配置，系统默认采用该策略。</td></tr></tbody></table><h2 id="约束说明">约束说明<a class="header-anchor" href="#约束说明">​</a></h2><p>无</p><h2 id="调用示例">调用示例<a class="header-anchor" href="#调用示例">​</a></h2><p>如下示例中查询当前是否使用<code>SetSaturationFlag</code>设置的全局饱和模式。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="kt">bool</span><span class="w"> </span><span class="n">useGlobal</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">AscendC</span><span class="o">::</span><span class="n">GetSaturationStrategy</span><span class="p">()</span><span class="w"> </span><span class="o">==</span><span class="w"> </span><span class="n">AscendC</span><span class="o">::</span><span class="n">OverrideStrategy</span><span class="o">::</span><span class="n">USE_GLOBAL</span><span class="p">;</span>
</code></pre></div></article></div>`,1)])])}const v=t(i,[["render",n]]);export{S as __pageData,v as default};
